[package]
name = "plugin_moxa_syslog"
version = "0.1.0"
edition = "2021"

# See more keys and their definitions at https://doc.rust-lang.org/cargo/reference/manifest.html

[dependencies]
actix-web = "4"
chrono = "0.4"
once_cell = "1.21.3"
# openssl = "0.10.42"
openssl = { version = "0.10.68", features = ["vendored"] }
regex = "1"
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"

lib_moxa_rust_debug_log_ng = { path = "../../lib_moxa_rust_debug_log_ng-custom" }
lib_moxa_rust_encrypt = { path = "../../lib_moxa_rust_encrypt-custom" }
lib_moxa_rust_event_action = { path = "../../lib_moxa_rust_event_action-custom" }
rust_moxa_common = { path = "../../rust_moxa_common-custom" }

